class Solution {
public:
    int digitFrequencyScore(int n) {
        string s = to_string(n);
        int cnt[10] = {0};
        for (char c : s) cnt[c - '0']++;
        int score = 0;
        for (int d = 0; d < 10; d++) score += d * cnt[d];
        return score;
    }
};

