class Solution {
    public int digitFrequencyScore(int n) {
        String s = Integer.toString(n);
        int[] cnt = new int[10];
        for (char c : s.toCharArray()) cnt[c - '0']++;
        int score = 0;
        for (int d = 0; d < 10; d++) score += d * cnt[d];
        return score;
    }
}

